record.field:
for rec in records:
    # Check Fleet Vehicle Log Services (fleet.vehicle.log.services)
    if 'fleet.vehicle.log.services' in env:
        running_services = env['fleet.vehicle.log.services'].search([
            ('vehicle_id', '=', rec.id),
            ('state', 'in', ['new', 'running'])
        ])
        if running_services:
            srv_names = ", ".join(running_services.mapped('description') or running_services.mapped('name') or ['Vehicle Service'])
            raise UserError(f"Cannot set bike '{rec.display_name}' to Available because there are active vehicle services in progress: {srv_names}. Please complete or cancel all running vehicle services first.")

    st = env.company.x_studio_default_bike_state_id or env.ref('bike_lease_saas.vehicle_state_available', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Available')], limit=1)
    rec.write({'state_id': st.id if st else False})

for rec in records:
    st = env.ref('bike_lease_saas.vehicle_state_maintenance', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Maintenance')], limit=1)
    rec.write({'state_id': st.id if st else False})

for rec in records:
    st = env.ref('bike_lease_saas.vehicle_state_retired', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Retired')], limit=1)
    rec.write({'state_id': st.id if st else False})

for rec in records:
    if not rec.x_name or rec.x_name in ('New', 'new', 'NEW'):
        seq = env['ir.sequence'].next_by_code('x_lease_application') or 'New'
        rec.write({'x_name': seq})

for rec in records:
    if not rec.x_name or rec.x_name in ('New', 'new', 'NEW'):
        seq = env['ir.sequence'].next_by_code('x_lease_contract') or 'New'
        rec.write({'x_name': seq})

for rec in records:
    if rec.x_studio_bike and rec.x_studio_bike.state_id and rec.x_studio_bike.state_id.name != 'Available':
        raise UserError("The selected bike '%s' is not available for leasing (Current Status: %s). Please select an available bike." % (rec.x_studio_bike.display_name or '', rec.x_studio_bike.state_id.name or ''))
    rec.write({
        'x_studio_selection_1': 'Submitted',
        'x_studio_date': datetime.date.today(),
    })

for rec in records:
    state_avail = env.company.x_studio_default_bike_state_id or env.ref('bike_lease_saas.vehicle_state_available', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Available')], limit=1)
    state_res = env.ref('bike_lease_saas.vehicle_state_reserved', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Reserved')], limit=1)
    if not rec.x_studio_bike and rec.x_studio_bike_model:
        domain = [('model_id', '=', rec.x_studio_bike_model.id)]
        if state_avail:
            domain.append(('state_id', '=', state_avail.id))
        else:
            domain.append(('state_id.name', '=', 'Available'))
        avail_bike = env['fleet.vehicle'].search(domain, limit=1)
        if avail_bike:
            rec.write({'x_studio_bike': avail_bike.id})
    if not rec.x_studio_bike:
        raise UserError("No available bike found for model '%s'. Please make a bike available before approving." % (rec.x_studio_bike_model.display_name if rec.x_studio_bike_model else 'N/A'))
    if rec.x_studio_bike.vehicle_type != 'bike':
        raise UserError("The selected vehicle '%s' is not a bike. Only bike vehicles can be leased." % (rec.x_studio_bike.display_name or ''))
    if rec.x_studio_bike.state_id and rec.x_studio_bike.state_id.name != 'Available':
        raise UserError("The selected bike '%s' is not available for leasing (Current Status: %s). Please select an available bike." % (rec.x_studio_bike.display_name or '', rec.x_studio_bike.state_id.name or ''))
    today = datetime.date.today()
    rec.write({
        'x_studio_selection_1': 'Approved',
        'x_studio_date': today,
    })
    if rec.x_studio_bike:
        rec.x_studio_bike.write({'state_id': state_res.id if state_res else False})
    existing = rec.x_studio_contract_id or env['x_lease_contract'].search([('x_studio_application_id', '=', rec.id)], limit=1)
    if not existing:
        contract = env['x_lease_contract'].create({
            'x_studio_partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
            'x_studio_bike_model': rec.x_studio_bike_model.id if rec.x_studio_bike_model else False,
            'x_studio_bike': rec.x_studio_bike.id if rec.x_studio_bike else False,
            'x_studio_lease_plan': rec.x_studio_lease_plan.id if rec.x_studio_lease_plan else False,
            'x_studio_date': rec.x_studio_lease_start_date or today,
            'x_studio_selection_1': 'Draft',
            'x_studio_application_id': rec.id,
        })
        rec.write({'x_studio_contract_id': contract.id})
    else:
        rec.write({'x_studio_contract_id': existing.id})
    # Send approval email to customer
    template = env.ref('bike_lease_saas.mail_template_lease_app_approved', raise_if_not_found=False)
    if template:
        template.send_mail(rec.id, force_send=True)

for rec in records:
    if rec.x_studio_application_id:
        app = rec.x_studio_application_id
        app.write({
            'x_studio_selection_1': 'Rejected',
            'x_studio_rejection_reason_ids': [(6, 0, rec.x_studio_rejection_reason_ids.ids)],
        })
        template = env.ref('bike_lease_saas.mail_template_lease_app_rejected', raise_if_not_found=False)
        if template:
            template.send_mail(app.id, force_send=True)

for rec in records:
    rec.write({
        'x_studio_selection_1': 'Draft',
        'x_studio_reason': False,
        'x_studio_rejection_reason_ids': [(5, 0, 0)],
    })

for rec in records:
    if rec.x_studio_bike and rec.x_studio_bike.model_id != rec.x_studio_bike_model:
        rec.update({'x_studio_bike': False})

for rec in records:
    inv = rec.x_studio_deposit_invoice_id
    if not inv and rec.x_studio_lease_plan:
        plan = rec.x_studio_lease_plan
        amt = plan.x_studio_security_deposit or 0.0
        if amt <= 0:
            amt = plan.x_studio_value or 0.0
        if amt > 0:
            inv = env['account.move'].create({
                'move_type': 'out_invoice',
                'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
                'invoice_date': datetime.date.today(),
                'invoice_line_ids': [(0, 0, {
                    'name': f"Security Deposit - Contract {rec.x_name}",
                    'quantity': 1,
                    'price_unit': amt,
                })],
            })
            rec.write({'x_studio_deposit_invoice_id': inv.id})
            try:
                inv.action_post()
            except Exception:
                pass
    if inv and inv.state == 'draft':
        try:
            inv.action_post()
        except Exception:
            pass

    plan = rec.x_studio_lease_plan
    start_date = rec.x_studio_date or datetime.date.today()

    if plan:
        duration = plan.x_studio_lease_duration or 1
        unit = plan.x_studio_duration_unit or 'Months'
        if unit == 'Days':
            end_date = start_date + datetime.timedelta(days=duration)
        elif unit == 'Weeks':
            end_date = start_date + datetime.timedelta(days=7 * duration)
        elif unit == 'Years':
            end_date = start_date + dateutil.relativedelta.relativedelta(years=duration)
        else:
            end_date = start_date + dateutil.relativedelta.relativedelta(months=duration)
    else:
        end_date = start_date + dateutil.relativedelta.relativedelta(months=1)

    rec.write({
        'x_studio_selection_1': 'Active',
        'x_studio_end_date': end_date,
    })

    if rec.x_studio_bike:
        st = env.ref('bike_lease_saas.vehicle_state_leased', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Leased')], limit=1)
        rec.x_studio_bike.write({'state_id': st.id if st else False})

    if plan and not rec.x_studio_installment_ids:
        freq = plan.x_studio_payment_frequency or 'Monthly'
        current_date = start_date
        idx = 1
        bike = rec.x_studio_bike
        daily_charge = (bike.x_studio_additional_daily_charge or 0.0) if (bike and bike.x_studio_has_additional_charge) else 0.0
        while current_date < end_date:
            if freq == 'Daily':
                next_date = current_date + datetime.timedelta(days=1)
            elif freq == 'Weekly':
                next_date = current_date + datetime.timedelta(days=7)
            elif freq == 'Quarterly':
                next_date = current_date + dateutil.relativedelta.relativedelta(months=3)
            elif freq == 'Yearly':
                next_date = current_date + dateutil.relativedelta.relativedelta(years=1)
            else:
                next_date = current_date + dateutil.relativedelta.relativedelta(months=1)

            period_end = min(next_date, end_date)
            days_in_period = (period_end - current_date).days
            base_fee = plan.x_studio_value or 0.0
            total_amount = base_fee + (daily_charge * days_in_period)

            env['x_lease_installment'].create({
                'x_name': f"Installment #{idx}",
                'x_studio_contract_id': rec.id,
                'x_studio_date': current_date,
                'x_studio_amount': total_amount,
                'x_studio_status': 'Draft',
                'x_studio_currency_id': plan.x_studio_currency_id.id if plan.x_studio_currency_id else False,
            })
            idx += 1
            current_date = next_date

for wiz in records:
    rec = wiz.x_studio_contract_id
    if not rec:
        continue

    dep = rec.x_studio_lease_plan.x_studio_security_deposit if rec.x_studio_lease_plan else 0.0
    need_service = wiz.x_studio_service_needed
    repair = (wiz.x_studio_repair_charge or 0.0) if need_service else 0.0
    refund_net = dep - repair

    created_move = False
    if refund_net > 0:
        created_move = env['account.move'].create({
            'move_type': 'out_refund',
            'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
            'invoice_date': datetime.date.today(),
            'invoice_line_ids': [(0, 0, {
                'name': f"Security Deposit Refund (after ${repair:.2f} repair deduction) - Contract {rec.x_name}",
                'quantity': 1,
                'price_unit': refund_net,
            })],
        })
    elif refund_net < 0:
        extra_due = abs(refund_net)
        created_move = env['account.move'].create({
            'move_type': 'out_invoice',
            'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
            'invoice_date': datetime.date.today(),
            'invoice_line_ids': [(0, 0, {
                'name': f"Excess Bike Repair / Service Fees (Deposit ${dep:.2f} absorbed) - Contract {rec.x_name}",
                'quantity': 1,
                'price_unit': extra_due,
            })],
        })

    vals = {
        'x_studio_bike_returned': True,
        'x_studio_service_needed': need_service,
        'x_studio_repair_charge': repair,
        'x_studio_issue_ids': [(6, 0, wiz.x_studio_issue_ids.ids)] if need_service else [(5, 0, 0)],
    }
    if created_move:
        vals['x_studio_return_invoice_id'] = created_move.id
    rec.write(vals)

    if rec.x_studio_bike:
        target_ref = 'bike_lease_saas.vehicle_state_maintenance' if need_service else 'bike_lease_saas.vehicle_state_available'
        target_name = 'Maintenance' if need_service else 'Available'
        st = False
        if not need_service and env.company.x_studio_default_bike_state_id:
            st = env.company.x_studio_default_bike_state_id
        if not st:
            st = env.ref(target_ref, raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', target_name)], limit=1)
        rec.x_studio_bike.write({'state_id': st.id if st else False})

        if need_service:
            issues = wiz.x_studio_issue_ids
            issue_names = ", ".join(issues.mapped('x_name')) if issues else "Inspection Service Needed"
            req_desc = f"Contract: {rec.x_name}\nCustomer: {rec.x_studio_partner_id.name if rec.x_studio_partner_id else 'N/A'}\nIssues Found: {issue_names}\nEstimated Repair Charge: ${repair:.2f}"
            env['fleet.vehicle.log.services'].create({
                'vehicle_id': rec.x_studio_bike.id,
                'description': f"Return Maintenance: {issue_names}\n{req_desc}",
                'amount': repair,
                'state': 'running',
            })

    # Send vehicle return & deposit settlement email to customer
    template = env.ref('bike_lease_saas.mail_template_vehicle_return_settlement', raise_if_not_found=False)
    if template:
        template.send_mail(rec.id, force_send=True)

    if created_move:
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Return Settlement Document',
            'res_model': 'account.move',
            'res_id': created_move.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    if not rec.x_studio_all_invoices_paid:
        raise UserError("All contract installments and deposit invoices must be fully paid before completing the contract.")
    rec.write({'x_studio_selection_1': 'Completed'})
    try:
        rec.message_post(body="Lease contract completed. Vehicle is pending return inspection.")
    except Exception:
        pass

for rec in records:
    today = datetime.date.today()
    app = env['x_lease_application'].create({
        'x_studio_partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
        'x_studio_bike_model': rec.x_studio_bike_model.id if rec.x_studio_bike_model else False,
        'x_studio_bike': rec.x_studio_bike.id if rec.x_studio_bike else False,
        'x_studio_lease_plan': rec.x_studio_lease_plan.id if rec.x_studio_lease_plan else False,
        'x_studio_date': today,
        'x_studio_lease_start_date': today,
        'x_studio_selection_1': 'Draft',
    })

    try:
        rec.message_post(body=f"Renewal Lease Application created: {app.x_name or 'Draft Application'}")
    except Exception:
        pass

    action = {
        'type': 'ir.actions.act_window',
        'name': 'Renewal Lease Application',
        'res_model': 'x_lease_application',
        'res_id': app.id,
        'view_mode': 'form',
        'target': 'current',
    }

for rec in records:
    today = datetime.date.today()

    # 1. Identify all past unpaid installments (due on or before today and not paid)
    past_unpaid_installments = rec.x_studio_installment_ids.filtered(
        lambda i: i.x_studio_date <= today and i.x_studio_status != 'Paid'
    )

    # 2. Identify all future unpaid installments (due after today and not paid)
    future_unpaid_installments = rec.x_studio_installment_ids.filtered(
        lambda i: i.x_studio_date > today and i.x_studio_status != 'Paid'
    )

    # Collect any existing open/draft invoices from past unpaid installments or deposit
    old_unpaid_invoices = past_unpaid_installments.mapped('x_studio_invoice_id').filtered(
        lambda inv: inv and inv.state != 'cancel' and inv.payment_state not in ('paid', 'in_payment')
    )
    if rec.x_studio_deposit_invoice_id and rec.x_studio_deposit_invoice_id.state != 'cancel' and rec.x_studio_deposit_invoice_id.payment_state not in ('paid', 'in_payment'):
        old_unpaid_invoices |= rec.x_studio_deposit_invoice_id

    # Add any open/draft invoice linked to future installments so we can cancel old draft invoices
    for f_inst in future_unpaid_installments:
        if f_inst.x_studio_invoice_id and f_inst.x_studio_invoice_id.state != 'cancel' and f_inst.x_studio_invoice_id.payment_state not in ('paid', 'in_payment'):
            old_unpaid_invoices |= f_inst.x_studio_invoice_id

    # Clean up and unlink all future unpaid installments
    future_unpaid_installments.unlink()

    # 3. Check if there are past unpaid dues
    has_unpaid_past = bool(past_unpaid_installments or old_unpaid_invoices)

    created_move = False
    if has_unpaid_past:
        invoice_lines = []

        # Add line for each past unpaid installment
        for inst in past_unpaid_installments:
            invoice_lines.append((0, 0, {
                'name': f"Lease Installment (Termination Settlement) - {rec.x_name} ({inst.x_name})",
                'quantity': 1,
                'price_unit': inst.x_studio_amount,
            }))
            late_fee = inst.x_studio_late_fee_amount or 0.0
            if late_fee > 0:
                invoice_lines.append((0, 0, {
                    'name': f"Late Payment Penalty Fee - {rec.x_name} ({inst.x_name})",
                    'quantity': 1,
                    'price_unit': late_fee,
                }))

        # If deposit invoice was unpaid and not linked to installments, add deposit line
        if rec.x_studio_deposit_invoice_id and rec.x_studio_deposit_invoice_id in old_unpaid_invoices:
            deposit_inst_invoices = past_unpaid_installments.mapped('x_studio_invoice_id')
            if rec.x_studio_deposit_invoice_id not in deposit_inst_invoices:
                for line in rec.x_studio_deposit_invoice_id.invoice_line_ids:
                    invoice_lines.append((0, 0, {
                        'name': line.name or f"Security Deposit Arrears - {rec.x_name}",
                        'quantity': line.quantity or 1,
                        'price_unit': line.price_unit,
                    }))

        if invoice_lines:
            created_move = env['account.move'].create({
                'move_type': 'out_invoice',
                'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
                'invoice_date': today,
                'invoice_line_ids': invoice_lines,
            })
            try:
                created_move.action_post()
            except Exception:
                pass

            # Link past unpaid installments to the new termination invoice
            for inst in past_unpaid_installments:
                inst.write({
                    'x_studio_invoice_id': created_move.id,
                    'x_studio_status': 'Invoiced',
                })

            if rec.x_studio_deposit_invoice_id in old_unpaid_invoices:
                rec.write({'x_studio_deposit_invoice_id': created_move.id})

            # Cancel old open/draft invoices that were replaced by created_move
            for old_inv in old_unpaid_invoices:
                if old_inv != created_move:
                    try:
                        if old_inv.state == 'posted':
                            old_inv.button_draft()
                        old_inv.button_cancel()
                    except Exception:
                        old_inv.write({'state': 'cancel'})

    # Double check no remaining unpaid future installments exist
    rem_future = rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_date > today and i.x_studio_status != 'Paid')
    if rem_future:
        rem_future.unlink()

    target_move = created_move or (old_unpaid_invoices.filtered(lambda inv: inv.state != 'cancel' and inv.payment_state not in ('paid', 'in_payment'))[:1])

    if target_move and target_move.payment_state not in ('paid', 'in_payment'):
        rec.write({'x_studio_pending_termination': True})
        msg = f"Early termination requested. Final termination invoice ({target_move.name or 'Invoice'}) created and opened for dues up to today. Contract will transition to Terminated once invoice is paid."
        try:
            rec.message_post(body=msg)
        except Exception:
            pass
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Termination Invoice',
            'res_model': 'account.move',
            'res_id': target_move.id,
            'view_mode': 'form',
            'target': 'current',
        }
    else:
        rec.write({'x_studio_selection_1': 'Terminated', 'x_studio_pending_termination': False})
        msg = "Lease contract terminated early. All dues up to today are settled. Vehicle pending return inspection."
        try:
            rec.message_post(body=msg)
        except Exception:
            pass

for rec in records:
    rec.write({'x_studio_selection_1': 'Cancelled'})
    if rec.x_studio_bike:
        st = env.company.x_studio_default_bike_state_id or env.ref('bike_lease_saas.vehicle_state_available', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Available')], limit=1)
        rec.x_studio_bike.write({'state_id': st.id if st else False})

for rec in records:
    rec.write({'x_studio_selection_1': 'Draft'})
    if rec.x_studio_bike:
        st = env.ref('bike_lease_saas.vehicle_state_reserved', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Reserved')], limit=1)
        rec.x_studio_bike.write({'state_id': st.id if st else False})

for rec in records:
    if rec.x_studio_application_id:
        action = {
            'type': 'ir.actions.act_window',
            'res_model': 'x_lease_application',
            'res_id': rec.x_studio_application_id.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    if rec.x_studio_bike:
        action = {
            'type': 'ir.actions.act_window',
            'res_model': 'fleet.vehicle',
            'res_id': rec.x_studio_bike.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    draft_installments = rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_status == 'Draft')
    if not draft_installments:
        raise UserError("All installments for this lease contract have already been invoiced.")

    installments_to_invoice = draft_installments[:1]
    created_move = False
    if not installments_to_invoice and not rec.x_studio_installment_ids:
        amount = rec.x_studio_lease_plan.x_studio_value if rec.x_studio_lease_plan else 0.0
        created_move = env['account.move'].create({
            'move_type': 'out_invoice',
            'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
            'invoice_date': datetime.date.today(),
            'invoice_line_ids': [(0, 0, {
                'name': f"Lease Contract Payment - {rec.x_name}",
                'quantity': 1,
                'price_unit': amount,
            })],
        })
    all_past_invoices = rec.x_studio_installment_ids.mapped('x_studio_invoice_id').filtered(
        lambda inv: inv and inv.state != 'cancel' and inv.payment_state not in ('paid', 'in_payment')
    )
    if rec.x_studio_deposit_invoice_id and rec.x_studio_deposit_invoice_id.state != 'cancel' and rec.x_studio_deposit_invoice_id.payment_state not in ('paid', 'in_payment'):
        all_past_invoices |= rec.x_studio_deposit_invoice_id

    invoice_lines = []
    for old_inv in all_past_invoices:
        for line in old_inv.invoice_line_ids:
            line_name = line.name or "Arrears Line"
            if not line_name.startswith("Arrears:"):
                line_name = f"Arrears: {line_name}"
            invoice_lines.append((0, 0, {
                'name': line_name,
                'quantity': line.quantity or 1,
                'price_unit': line.price_unit,
            }))

    for inst in installments_to_invoice:
        invoice_lines.append((0, 0, {
            'name': f"Lease Installment - {rec.x_name} ({inst.x_name})",
            'quantity': 1,
            'price_unit': inst.x_studio_amount,
        }))
        late_fee = inst.x_studio_late_fee_amount or 0.0
        if late_fee > 0:
            invoice_lines.append((0, 0, {
                'name': f"Late Payment Penalty Fee - {rec.x_name} ({inst.x_name})",
                'quantity': 1,
                'price_unit': late_fee,
            }))

    created_move = env['account.move'].create({
        'move_type': 'out_invoice',
        'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
        'invoice_date': datetime.date.today(),
        'invoice_line_ids': invoice_lines,
    })

    for inst in installments_to_invoice:
        inst.write({
            'x_studio_invoice_id': created_move.id,
            'x_studio_status': 'Invoiced',
        })

    for past_inst in rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_invoice_id in all_past_invoices):
        past_inst.write({'x_studio_invoice_id': created_move.id})

    if rec.x_studio_deposit_invoice_id in all_past_invoices:
        rec.write({'x_studio_deposit_invoice_id': created_move.id})

    for old_inv in all_past_invoices:
        try:
            if old_inv.state == 'posted':
                old_inv.button_draft()
            old_inv.button_cancel()
        except Exception:
            old_inv.write({'state': 'cancel'})

    if created_move:
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Customer Invoice',
            'res_model': 'account.move',
            'res_id': created_move.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    target_invoice = rec.x_studio_deposit_invoice_id
    if not target_invoice and rec.x_studio_lease_plan:
        plan = rec.x_studio_lease_plan
        amt = plan.x_studio_security_deposit or 0.0
        if amt <= 0:
            amt = plan.x_studio_value or 0.0

        target_invoice = env['account.move'].create({
            'move_type': 'out_invoice',
            'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
            'invoice_date': datetime.date.today(),
            'invoice_line_ids': [(0, 0, {
                'name': f"Security Deposit - Contract {rec.x_name}",
                'quantity': 1,
                'price_unit': amt,
            })],
        })
        rec.write({'x_studio_deposit_invoice_id': target_invoice.id})

    if target_invoice and target_invoice.payment_state in ('paid', 'in_payment'):
        # If already paid, activate contract & create installment schedule
        if rec.x_studio_selection_1 == 'Draft':
            rec.write({
                'x_studio_selection_1': 'Active',
                'x_studio_deposit_paid': True,
            })
            if rec.x_studio_bike:
                st = env.ref('bike_lease_saas.vehicle_state_leased', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Leased')], limit=1)
                rec.x_studio_bike.write({'state_id': st.id if st else False})
            plan = rec.x_studio_lease_plan
            start_date = rec.x_studio_date or datetime.date.today()
            if plan:
                duration = plan.x_studio_lease_duration or 1
                unit = plan.x_studio_duration_unit or 'Months'
                if unit == 'Days':
                    end_date = start_date + datetime.timedelta(days=duration)
                elif unit == 'Weeks':
                    end_date = start_date + datetime.timedelta(days=7 * duration)
                elif unit == 'Years':
                    end_date = start_date + dateutil.relativedelta.relativedelta(years=duration)
                else:
                    end_date = start_date + dateutil.relativedelta.relativedelta(months=duration)
            else:
                end_date = start_date + dateutil.relativedelta.relativedelta(months=1)
            rec.write({'x_studio_end_date': end_date})
            if plan and not rec.x_studio_installment_ids:
                freq = plan.x_studio_payment_frequency or 'Monthly'
                current_date = start_date
                idx = 1
                bike = rec.x_studio_bike
                daily_charge = (bike.x_studio_additional_daily_charge or 0.0) if (bike and bike.x_studio_has_additional_charge) else 0.0
                while current_date < end_date:
                    if freq == 'Daily':
                        next_date = current_date + datetime.timedelta(days=1)
                    elif freq == 'Weekly':
                        next_date = current_date + datetime.timedelta(days=7)
                    elif freq == 'Quarterly':
                        next_date = current_date + dateutil.relativedelta.relativedelta(months=3)
                    elif freq == 'Yearly':
                        next_date = current_date + dateutil.relativedelta.relativedelta(years=1)
                    else:
                        next_date = current_date + dateutil.relativedelta.relativedelta(months=1)
                    period_days = (next_date - current_date).days
                    base_rate = plan.x_studio_value or 0.0
                    total_amount = base_rate + (daily_charge * period_days)
                    env['x_lease_installment'].create({
                        'x_studio_contract_id': rec.id,
                        'x_name': f"Installment #{idx}",
                        'x_studio_date': current_date,
                        'x_studio_amount': base_rate,
                        'x_studio_total_amount': total_amount,
                        'x_studio_status': 'Draft',
                    })
                    idx += 1
                    current_date = next_date

    if target_invoice:
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Security Deposit Invoice',
            'res_model': 'account.move',
            'res_id': target_invoice.id,
            'view_mode': 'form',
            'target': 'current',
        }

for move in records:
