            rec.write({'x_studio_end_date': end_date})
            if plan and not rec.x_studio_installment_ids:
                freq = plan.x_studio_payment_frequency or 'Monthly'
                current_date = start_date
                idx = 1
                bike = rec.x_studio_bike
                daily_charge = (bike.x_studio_additional_daily_charge or 0.0) if (bike and bike.x_studio_has_additional_charge) else 0.0
                while current_date < end_date:
                    if freq == 'Daily':
                        next_date = current_date + datetime.timedelta(days=1)
                    elif freq == 'Weekly':
                        next_date = current_date + datetime.timedelta(days=7)
                    elif freq == 'Quarterly':
                        next_date = current_date + dateutil.relativedelta.relativedelta(months=3)
                    elif freq == 'Yearly':
                        next_date = current_date + dateutil.relativedelta.relativedelta(years=1)
                    else:
                        next_date = current_date + dateutil.relativedelta.relativedelta(months=1)
                    period_days = (next_date - current_date).days
                    base_rate = plan.x_studio_value or 0.0
                    total_amount = base_rate + (daily_charge * period_days)
                    env['x_lease_installment'].create({
                        'x_studio_contract_id': rec.id,
                        'x_name': f"Installment #{idx}",
                        'x_studio_date': current_date,
                        'x_studio_amount': base_rate,
                        'x_studio_total_amount': total_amount,
                        'x_studio_status': 'Draft',
                    })
                    idx += 1
                    current_date = next_date

for rec in records:
    invoices = rec.x_studio_installment_ids.mapped('x_studio_invoice_id')
    if rec.x_studio_deposit_invoice_id:
        invoices |= rec.x_studio_deposit_invoice_id
    if rec.x_studio_return_invoice_id:
        invoices |= rec.x_studio_return_invoice_id
    action = {
        'type': 'ir.actions.act_window',
        'name': 'Customer Invoices',
        'res_model': 'account.move',
        'view_mode': 'list,form',
        'domain': [('id', 'in', invoices.ids)],
    }
    if len(invoices) == 1:
        action['res_id'] = invoices.id
        action['view_mode'] = 'form'

for rec in records:
    contracts = env['x_lease_contract'].search(['|', ('x_studio_deposit_invoice_id', '=', rec.id), ('x_studio_return_invoice_id', '=', rec.id)])
    if not contracts:
        installments = env['x_lease_installment'].search([('x_studio_invoice_id', '=', rec.id)])
        contracts = installments.mapped('x_studio_contract_id')

    action = {
        'type': 'ir.actions.act_window',
        'name': 'Lease Contract',
        'res_model': 'x_lease_contract',
        'view_mode': 'list,form',
        'domain': [('id', 'in', contracts.ids)],
    }
    if len(contracts) == 1:
        action['res_id'] = contracts.id
        action['view_mode'] = 'form'

for rec in records:
    if rec.x_studio_invoice_id:
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Customer Invoice',
            'res_model': 'account.move',
            'res_id': rec.x_studio_invoice_id.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    app = env['x_lease_application'].create({
        'x_studio_partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
        'x_studio_bike_model': rec.x_studio_bike_model.id if rec.x_studio_bike_model else False,
        'x_studio_bike': rec.x_studio_bike.id if rec.x_studio_bike else False,
        'x_studio_lease_plan': rec.x_studio_lease_plan.id if rec.x_studio_lease_plan else False,
        'x_studio_lease_start_date': datetime.date.today(),
        'x_studio_selection_1': 'Draft',
    })
    try:
        rec.message_post(body=f"Renewal Application created: {app.x_name or 'New Application'}")
    except Exception:
        pass
    action = {
        'type': 'ir.actions.act_window',
        'name': 'Renewal Lease Application',
        'res_model': 'x_lease_application',
        'res_id': app.id,
        'view_mode': 'form',
        'target': 'current',
    }

for move in records:
    if move.payment_state in ('paid', 'in_payment'):
        installments = env['x_lease_installment'].search([('x_studio_invoice_id', '=', move.id)])
        for inst in installments:
            inst.write({
                'x_studio_payment_state': 'paid',
                'x_studio_status': 'Paid',
                'x_studio_is_overdue': False,
            })

        contracts = installments.mapped('x_studio_contract_id')
        dep_contracts = env['x_lease_contract'].search([('x_studio_deposit_invoice_id', '=', move.id)])
        pending_contracts = env['x_lease_contract'].search([('x_studio_pending_termination', '=', True)])
        for cnt in (contracts | dep_contracts | pending_contracts):
            if ('x_studio_pending_termination' in cnt._fields and cnt.x_studio_pending_termination):
                unpaid_due = cnt.x_studio_installment_ids.filtered(
                    lambda i: i.x_studio_date <= datetime.date.today() and (not i.x_studio_invoice_id or i.x_studio_invoice_id.payment_state not in ('paid', 'in_payment'))
                )
                dep_unpaid = cnt.x_studio_deposit_invoice_id and cnt.x_studio_deposit_invoice_id.payment_state not in ('paid', 'in_payment')
                if not unpaid_due and not dep_unpaid:
                    cnt.write({
                        'x_studio_selection_1': 'Terminated',
                        'x_studio_pending_termination': False,
                    })
                    try:
                        cnt.message_post(body="Termination invoice paid. Contract is now officially Terminated. Vehicle pending return inspection.")
                    except Exception:
                        pass

for srv in records:
    if srv.state in ('done', 'cancelled') and srv.vehicle_id:
        bike = srv.vehicle_id
        if bike.state_id and bike.state_id.name == 'Maintenance':
            running_services = env['fleet.vehicle.log.services'].search_count([
                ('vehicle_id', '=', bike.id),
                ('state', 'in', ['new', 'running'])
            ])
            if not running_services:
                st = env.company.x_studio_default_bike_state_id or env.ref('bike_lease_saas.vehicle_state_available', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Available')], limit=1)
                bike.write({'state_id': st.id if st else False})

for rec in records:
    if not rec.x_studio_bike_returned:
        raise UserError("Report is only available for contracts where the bike has been returned and inspected.")
action = env.ref('bike_lease_saas.action_report_lease_contract').report_action(records)

comps = records if records else env.company
for comp in comps:
    c = comp if comp._name == 'res.company' else env.company
    allowed_stages = c.x_studio_bike_state_ids if (c and 'x_studio_bike_state_ids' in c._fields) else env.company.x_studio_bike_state_ids
    if not allowed_stages:
        allowed_stages = env['fleet.vehicle.state'].search([('name', 'in', ['Available', 'Reserved', 'Leased', 'Maintenance', 'Retired'])])

    allowed_ids = set(allowed_stages.ids)
    for stage in env['fleet.vehicle.state'].search([]):
        if stage.id in allowed_ids:
            stage.write({'fold': False})
        else:
            stage.write({'fold': True})

for rec in records:
    if rec.vehicle_type == 'bike':
        st = env.company.x_studio_default_bike_state_id or env.ref('bike_lease_saas.vehicle_state_available', raise_if_not_found=False) or env['fleet.vehicle.state'].search([('name', '=', 'Available')], limit=1)
        allowed_ids = env.company.x_studio_bike_state_ids.ids if env.company.x_studio_bike_state_ids else []
        if st and (not rec.state_id or (allowed_ids and rec.state_id.id not in allowed_ids) or rec.state_id.name == 'New Request'):
            rec.write({'state_id': st.id})
